"use strict";

/*
 * Domains 11â€“20 are deliberately written as individual project briefs.  The
 * small constructor only keeps the renderer contract readable; it does not
 * supply copy, FAQs, skills, mistakes, or visuals.
 */
const project = (name, slug, primaryKeyword, accent, factsKey, facts, content, visual, catalogueDomain) => ({
  name, slug, primaryKeyword, accent, factsKey, facts,
  content: {
    ...content,
    // These are catalogue facts restated as an evidence checklist, not claims
    // about outcomes. They keep each page's practical submission guidance tied
    // to its own assigned project.
    evidenceNotes: [...(content.evidenceNotes || []), `Project scope: ${facts.taskBrief}`, `Validation focus: ${facts.validation}`, `Expected working tools or artifacts: ${facts.toolsExpected}`],
  },
  diagram: visual, catalogueDomain, pilot: true, qualityGatesPassed: true,
});

const svg = (title, desc, body) => `<svg viewBox="0 0 520 350" role="img" aria-labelledby="visual-title visual-desc"><title id="visual-title">${title}</title><desc id="visual-desc">${desc}</desc>${body}</svg>`;
const box = (x, y, w, h, label, detail = "") => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="10"/><text x="${x + 13}" y="${y - 12}">${label}</text>${detail ? `<text x="${x + 13}" y="${y + h / 2}">${detail}</text>` : ""}`;
