  rag: svg("Retrieval-grounded answer path", "PDF pages become traceable chunks, relevant evidence, a cited answer, or an explicit no-answer response.", `<g class="dp-boxes">${box(28,120,90,85,"PDF","page data")}${box(145,120,90,85,"CHUNKS","config")}${box(262,120,90,85,"RETRIEVE","evidence")}${box(380,120,110,85,"ANSWER","cite / abstain")}</g><path d="M118 162H145M235 162H262M352 162H380"/><g class="dp-notes"><text x="130" y="85">NO EVIDENCE â†’ SAY SO</text></g>`),
  nlp: svg("Sentiment analysis workbench", "Review text is cleaned, represented, compared across classifiers, and presented with class-level error evidence.", `<g class="dp-boxes">${box(30,118,100,88,"REVIEWS","labels")}${box(155,118,100,88,"TF-IDF","inspect")}${box(280,118,100,88,"COMPARE","metrics")}${box(405,118,85,88,"APP","trends")}</g><path d="M130 162H155M255 162H280M380 162H405"/><g class="dp-notes"><text x="116" y="260">language limits + representative errors</text></g>`),
