  business: svg("HR dashboard evidence chain", "Workforce rows are modelled into defined measures, segment views, and an honest stakeholder narrative.", `<g class="dp-boxes">${box(30,122,100,78,"ROWS","fields")}${box(155,122,100,78,"MODEL","measures")}${box(280,122,100,78,"VIEWS","filters")}${box(405,122,85,78,"MEMO","caveats")}</g><path d="M130 161H155M255 161H280M380 161H405"/><g class="dp-notes"><text x="92" y="267">aggregate only / KPI definitions visible</text></g>`),
  testing: svg("Quality signal stack", "A scoped plan feeds manual cases and Playwright checks; CI returns readable reports and traces for investigation.", `<g class="dp-boxes">${box(28,118,90,84,"SCOPE","risk")}${box(145,118,90,84,"CASES","manual")}${box(262,118,90,84,"PLAYWRIGHT","repeat")}${box(380,118,110,84,"CI REPORT","trace")}</g><path d="M118 160H145M235 160H262M352 160H380"/><g class="dp-notes"><text x="133" y="260">deterministic data + known gaps</text></g>`),
