const common = (p) => ({
  h1: p.h1, summary: p.summary, buildIntro: p.buildIntro, narrativeHeading: p.narrativeHeading,
  projectNarrative: p.narrative, forYou: p.forYou, notForYou: p.notForYou,
  progression: p.progression, selfCheck: p.selfCheck, skills: p.skills, links: p.links,
  mistakes: p.mistakes, cvPatterns: p.cv, credential: "GreyRocks is the issuer named in the HireeBridge certificate flow. After you complete and submit the assigned task and it receives explicit approval, a credential record is created with a unique credential ID and QR verification destination.",
  faqs: p.faqs, sibling: p.sibling,
  evidenceNotes: p.mistakes.map(([risk, remedy]) => `${risk}: ${remedy}`),
});

